CREATE FUNCTION F_MENU_HIDDEN_HIERARCHY(@sCode nvarchar(30))
RETURNS @tReturn table( emn_code nvarchar(30) COLLATE Latin1_General_BIN )
AS
BEGIN
   DECLARE @nLevel			int
   DECLARE @sCurrentCode	nvarchar(30)
   DECLARE @sParentCode    nvarchar(30)

   DECLARE @tStack TABLE ( emn_code nvarchar(30), LevelID int )

   INSERT INTO @tStack VALUES ( @sCode, 1 );
   SET @nLevel = 1;

   WHILE( @nLevel > 0 )
      BEGIN
         IF EXISTS (SELECT * FROM @tStack WHERE LevelID = @nLevel)
            BEGIN
               SELECT @sCurrentCode = emn_code from @tStack where LevelID = @nLevel;
               INSERT INTO @tReturn SELECT @sCurrentCode FROM r5extmenus WHERE emn_code = @sCurrentCode AND COALESCE(emn_hide, '-') = '+';
               DELETE FROM @tStack WHERE LevelID = @nLevel AND emn_code = @sCurrentCode;

               SET @sParentCode = null;

               SELECT @sParentCode = emn_parent
               FROM r5extmenus
               WHERE emn_code = @sCurrentCode;

               IF( @sParentCode IS NOT NULL )
                  BEGIN
                     INSERT INTO @tStack VALUES ( @sParentCode, @nLevel + 1 );
                     SET @nLevel = @nLevel + 1;
                  END
            END
         ELSE
            SET @nLevel = @nLevel - 1;
      END

   RETURN
END
