create PROCEDURE  O7BOOCOS 
	@nBookedcost		numeric(24,6) OUTPUT,
	@nBookedrate		numeric(24,12),
	@nBookedhours		numeric(24,6),
	@sChk				nvarchar(4) OUTPUT

AS
	SET NOCOUNT ON
   /* init */
	set @sChk         = N'0'
	set @nBookedcost = -3
	/* check mandatory parameters */
	IF  @nBookedrate  IS   NULL   OR  @nBookedhours       IS   NULL 
		begin
			set @sChk = N'1'
			set @nBookedcost = -2
			RETURN 
		end
	/* W0312T,  W0322T: Cost is rate time the hours */
	set @nBookedcost = @nBookedrate * @nBookedhours
	return


