  DECLARE @prt_udfnum01        NUMERIC( 24, 6 )
  DECLARE @prt_udfnum02        NUMERIC( 24, 6 )
  DECLARE @prt_udfnum03        NUMERIC( 24, 6 )
  DECLARE @prt_udfnum04        NUMERIC( 24, 6 )
  DECLARE @prt_udfnum05        NUMERIC( 24, 6 )
