  DECLARE @prt_udfchkbox03     NVARCHAR( 1 )
  DECLARE @prt_udfchkbox04     NVARCHAR( 1 )
  DECLARE @prt_udfchkbox05     NVARCHAR( 1 )
  DECLARE @pre_permit          NVARCHAR( 12 )
  DECLARE @pre_permit_org      NVARCHAR( 15 )
  DECLARE @pre_entity          NVARCHAR( 4 )
  DECLARE @pre_rentity         NVARCHAR( 4 )
  DECLARE @pre_rtype           NVARCHAR( 4 )
  DECLARE @pre_code            NVARCHAR( 50 )
  DECLARE @pre_sqlidentity     INT
  DECLARE @reviewtrigger       NVARCHAR( 8 )
  DECLARE @chk                 NVARCHAR( 4 )
  DECLARE @return              INT
  DECLARE @parentcode          NVARCHAR( 50 )
  DECLARE @parentorg           NVARCHAR( 50 )
  DECLARE @deforg              NVARCHAR( 15 )
  DECLARE @permsync            NVARCHAR( 2000 )
  DECLARE @permrrev            NVARCHAR( 2000 )

  /* Get default org, used for categories. */
  SET @deforg = dbo.o7dflt2( N'DEFORG')

  /* Get review trigger. */
  EXECUTE @return = r5o7_o7ucode @reviewtrigger OUTPUT, N'PRMU', N'RVTR', @chk OUTPUT

  /* Get Permit data to cascade. */
  SELECT @prt_autocreateptw = prt_autocreateptw,
         @prt_ptwtype       = prt_ptwtype,
         @prt_typeofwork    = prt_typeofwork,
         @prt_priority      = prt_priority,
         @prt_risk          = prt_risk,
         @prt_isolationtype = prt_isolationtype,
         @prt_lotorequired  = prt_lotorequired,
         @prt_udfchar01     = prt_udfchar01, 
         @prt_udfchar02     = prt_udfchar02, 
         @prt_udfchar03     = prt_udfchar03, 
         @prt_udfchar04     = prt_udfchar04, 
         @prt_udfchar05     = prt_udfchar05,
         @prt_udfchar06     = prt_udfchar06, 
         @prt_udfchar07     = prt_udfchar07, 
         @prt_udfchar08     = prt_udfchar08, 
         @prt_udfchar09     = prt_udfchar09, 
         @prt_udfchar10     = prt_udfchar10,
         @prt_udfchar11     = prt_udfchar11, 
         @prt_udfchar12     = prt_udfchar12, 
         @prt_udfchar13     = prt_udfchar13, 
         @prt_udfchar14     = prt_udfchar14, 
         @prt_udfchar15     = prt_udfchar15,
         @prt_udfchar16     = prt_udfchar16, 
         @prt_udfchar17     = prt_udfchar17, 
         @prt_udfchar18     = prt_udfchar18, 
         @prt_udfchar19     = prt_udfchar19, 
         @prt_udfchar20     = prt_udfchar20,
         @prt_udfchar21     = prt_udfchar21, 
         @prt_udfchar22     = prt_udfchar22, 
         @prt_udfchar23     = prt_udfchar23, 
         @prt_udfchar24     = prt_udfchar24, 
         @prt_udfchar25     = prt_udfchar25,
         @prt_udfchar26     = prt_udfchar26, 
         @prt_udfchar27     = prt_udfchar27, 
         @prt_udfchar28     = prt_udfchar28, 
         @prt_udfchar29     = prt_udfchar29, 
         @prt_udfchar30     = prt_udfchar30,
         @prt_udfnum01      = prt_udfnum01, 
         @prt_udfnum02      = prt_udfnum02, 
         @prt_udfnum03      = prt_udfnum03, 
         @prt_udfnum04      = prt_udfnum04, 
         @prt_udfnum05      = prt_udfnum05,
         @prt_udfdate01     = prt_udfdate01, 
         @prt_udfdate02     = prt_udfdate02, 
         @prt_udfdate03     = prt_udfdate03, 
         @prt_udfdate04     = prt_udfdate04, 
         @prt_udfdate05     = prt_udfdate05,
         @prt_udfchkbox01   = prt_udfchkbox01, 
         @prt_udfchkbox02   = prt_udfchkbox02, 
         @prt_udfchkbox03   = prt_udfchkbox03, 
         @prt_udfchkbox04   = prt_udfchkbox04, 
         @prt_udfchkbox05   = prt_udfchkbox05
  FROM   r5permits
  WHERE  prt_code     = @code
  AND    prt_org      = @org
  AND    prt_revision = @revision

  DECLARE pre CURSOR LOCAL STATIC FOR 
    /* Cursor to retrieve Permits for which review data should be reset. */
    SELECT pre_permit, pre_permit_org, pre_entity, pre_rentity, pre_rtype, pre_code, pre_sqlidentity
    FROM   r5permentities
    WHERE  pre_permit     = @code
    AND    pre_permit_org = @org

  OPEN pre 
  FETCH NEXT FROM pre INTO @pre_permit, @pre_permit_org, @pre_entity, @pre_rentity, @pre_rtype, @pre_code, @pre_sqlidentity
  WHILE @@FETCH_STATUS = 0
    BEGIN
      /* First retrieve code and org of parent, */
      IF @pre_rentity = N'STWO'     -- Standard Work Order
        BEGIN
          SET @parentcode = @pre_code
          SELECT @parentorg = stw_org
          FROM   r5standworks
          WHERE  stw_code = @pre_code
        END  
      ELSE IF @pre_rentity = N'PPM' -- Preventive Maintenance
        BEGIN
          SET @parentcode = SUBSTRING( @pre_code, 1, CHARINDEX( N'#', @pre_code ) - 1 )
          SELECT @parentorg = ppm_org
          FROM   r5ppms
          WHERE  ppm_code = @parentcode
        END  
      ELSE IF @pre_rtype = N'C'     -- Category
        BEGIN
          SET @parentcode = @pre_code
          SET @parentorg  = @deforg
        END  
      ELSE                          -- Asset and Location.
        BEGIN
          SET @parentcode = SUBSTRING( @pre_code, 1, CHARINDEX( N'#', @pre_code ) - 1 )
          SET @parentorg  = SUBSTRING( @pre_code, CHARINDEX( N'#', @pre_code ) + 1, 1000 )
        END  

      /* Get value for organization options. */
      EXECUTE @return = o7getorgoption @permsync OUTPUT, N'PERMSYNC', @parentorg, @chk OUTPUT 
      EXECUTE @return = o7getorgoption @permrrev OUTPUT, N'PERMRREV', @parentorg, @chk OUTPUT 

      IF @permsync = N'YES'
        /* Cascade Permit data to objects. */
        UPDATE r5permentities
        SET    pre_autocreateptw = @prt_autocreateptw,
               pre_ptwtype       = @prt_ptwtype,
               pre_typeofwork    = @prt_typeofwo


