create procedure O7CHKCRUSERFROMROLE
   @nReturn       	    integer OUTPUT, 	
   @sRole 	        nvarchar(20),
   @sFlags 	    	    nvarchar(3000) OUTPUT
AS 
	SET NOCOUNT ON
	SET IMPLICIT_TRANSACTIONS ON

    declare @sActive          nvarchar(1)    --r5roles.rol_active%TYPE;
    declare @sRequestor       nvarchar(1)    --r5roles.rol_requestor%TYPE;
    declare @sMobile          nvarchar(1)    --r5roles.rol_mobile%TYPE;
    declare @sConnector       nvarchar(1)    --r5roles.rol_connector%TYPE;
    declare @sBarCode         nvarchar(1)    --r5roles.rol_barcode%TYPE;
    declare @sAnalytics       nvarchar(1)    --r5roles.rol_analytics%TYPE;
    declare @sConsumer        nvarchar(1)    --r5roles.rol_advrepconsumer%TYPE;
    declare @sProfessional    nvarchar(1)    --r5roles.rol_advrepauthor%TYPE;
    declare @sMobileadm       nvarchar(1)    --r5roles.rol_mobileadm%TYPE;


    SELECT @sActive =   coalesce(rol_active, N'-'), 
        @sRequestor =   coalesce(rol_requestor, N'-'), 
        @sMobile =      coalesce(rol_mobile, N'-'), 
        @sConnector =   coalesce(rol_connector, N'-'), 
        @sBarCode =     coalesce(rol_barcode, N'-'),
		@sAnalytics =   coalesce(rol_analytics, N'-'),
		@sConsumer  =   coalesce(rol_advrepconsumer, N'-'),
		@sProfessional= coalesce(rol_advrepauthor, N'-'),
		@sMobileadm =   coalesce(rol_mobileadm, N'-')
    FROM r5roles
    WHERE rol_code = @sRole


    IF( @sActive = N'+' AND @sRequestor = N'+' )
        begin
            set @nReturn = 1
            return
        end

    -- Set flags to return
    set @sFlags = @sActive + @sRequestor + @sMobile + @sConnector + @sBarCode + @sAnalytics + @sConsumer + @sProfessional + @sMobileadm 
    set @nReturn = 0
    return


