				 @nObj_increment		numeric(24,6),
	             @sObj_pidno			nvarchar(80),
	             @sObj_piddrawing		nvarchar(80),
	             @nObj_serviceperc		numeric(24,6),
	             @nObj_devicetolfrom	numeric(24,6),
	             @nObj_devicetolto		numeric(24,6),
	             @sObj_devicetoltype	nvarchar(1),
	             @nObj_devicerangefrom	numeric(24,6),
	             @nObj_devicerangeto	numeric(24,6),
	             @nObj_outputrangefrom	numeric(24,6),
	             @nObj_outputrangeto	numeric(24,6),
	             @nObj_processtolfrom	numeric(24,6),
	             @nObj_processtolto		numeric(24,6),
	             @nObj_processrangefrom	numeric(24,6),
	             @nObj_processrangeto	numeric(24,6),
	             @sObj_sop				nvarchar(30),
	             @sObj_set				nvarchar(4),
	             @sObj_instrument		nvarchar(1),
	             @sObj_instrumenttype	nvarchar(1),
	             @sObj_loop				nvarchar(1)

	--	Note SRH - 06/09/2004: - SCR12554:  Due to the possibility that this procedure could be called with @sCategory
	--	set as an empty string as well as a null value, we
	--	have added a check here for empty string.  Without this check the values in r5objects are reset to
	--	null in the update if @sCategory is an empty string.

    IF @sCategory IS NOT NULL AND @sCategory <> ''
	begin
		SELECT  @sObj_testpointuom = obj_testpointuom,
	            @sObj_outputuom = obj_outputuom,
	            @nObj_precision = obj_precision,
	            @nObj_increment = obj_increment,
	            @sObj_pidno = obj_pidno,
	            @sObj_piddrawing = obj_piddrawing,
	            @nObj_serviceperc = obj_serviceperc,
	            @nObj_devicetolfrom = obj_devicetolfrom,
	            @nObj_devicetolto = obj_devicetolto,
	            @sObj_devicetoltype = obj_devicetoltype,
	            @nObj_devicerangefrom = obj_devicerangefrom,
	            @nObj_devicerangeto = obj_devicerangeto,
	            @nObj_outputrangefrom = obj_outputrangefrom,
	            @nObj_outputrangeto = obj_outputrangeto,
	            @nObj_processtolfrom = obj_processtolfrom,
	            @nObj_processtolto = obj_processtolto,
	            @nObj_processrangefrom = obj_processrangefrom,
	            @nObj_processrangeto = obj_processrangeto,
	            @sObj_sop = obj_sop,
	            @sObj_set = obj_set,
	            @sObj_instrument = obj_instrument,
	            @sObj_instrumenttype = obj_instrumenttype,
	            @sObj_loop = obj_loop
          FROM   r5objects
          WHERE  obj_code    = @sCategory
          AND    obj_obrtype = N'C'

	    /* First copy actual object data. */
	    UPDATE r5objects
	    SET    obj_testpointuom = @sObj_testpointuom,
	           obj_outputuom = @sObj_outputuom,
	           obj_precision = @nObj_precision,
	           obj_increment = @nObj_increment,
	           obj_pidno = @sObj_pidno,
	           obj_piddrawing = @sObj_piddrawing,
	           obj_serviceperc = @nObj_serviceperc,
	           obj_devicetolfrom = @nObj_devicetolfrom,
	           obj_devicetolto = @nObj_devicetolto,
	           obj_devicetoltype = @sObj_devicetoltype,
	           obj_devicerangefrom = @nObj_devicerangefrom,
	           obj_devicerangeto = @nObj_devicerangeto,
	           obj_outputrangefrom = @nObj_outputrangefrom,
	           obj_outputrangeto = @nObj_outputrangeto,
	           obj_processtolfrom = @nObj_processtolfrom,
	           obj_processtolto = @nObj_processtolto,
	           obj_processrangefrom = @nObj_processrangefrom,
	           obj_processrangeto = @nObj_processrangeto,
	           obj_sop = @sObj_sop,
	           obj_set = @sObj_set,
	           obj_instrument = @sObj_instrument,
	           obj_instrumenttype = @sObj_instrumenttype,
	           obj_loop  = @sObj_loop
	    WHERE  obj_code = @sObject
	    AND    obj_org  = @sOrg

	    /* Copy test point data. */
	    INSERT INTO r5objtestpoints( otp_object,
	                                 otp_object_org,
	                                 otp_set,
	                                 otp_seq,
	                                 otp_testpoint,
	                                 otp_testpointuom,
	                                 otp_output,
	                                 otp_outputuom,
	                                 otp_devicetolfrom,
	                                 otp_devicetolto,
	                                 otp_devicetoltype,
                                     otp_comments,
                                     otp_udfchar01,
                                     otp_udfchar02,
                                     otp_udfchar03,
                                     otp_udfchar04, 
                                     otp_udfchar05,
                                     otp_udfnum01,
                                     otp_udfnum02,
                                     otp_udfnum03,
                                     otp_udfnum04,
                                     otp_udfnum05,
                                     otp_udfdate01,
                                     otp_udfdate02,
                                     otp_udfdate03,
                                     otp_udfdate04,
                                     otp_udfdate05,
                                     otp_udfchkbox01,
                                     otp_udfchkbox02,
                                     otp_udfchkbox03,
                                     otp_udfchkbox04,
                                     otp_udfchkbox05,
                                     otp_precision
                                      )
	    SELECT @sObject,
	           @sOrg,
	           otp_set,
	           otp_seq,
	           otp_testpoint,
	           otp_testpointuom,
	           otp_output,
	           otp_outputuom,
	           otp_devicetolfrom,
	           otp_devicetolto,
	           otp_devicetoltype,
               otp_comments,
               otp_udfchar01,
               otp_udfchar02,
               otp_udfchar03,
               otp_udfchar04, 
               otp_udfchar05,
               otp_udfnum01,
               otp_udfnum02,
               otp_udfnum03,
               otp_udfnum04,
               otp_udfnum05,
               otp_udfdate01,
               otp_udfdate02,
               otp_udfdate03,
               otp_udfdate04,
               otp_udfdate05,
               otp_udfchkbox01,
               otp_udfchkbox02,
               otp_udfchkbox03,
               otp_udfchkbox04,
               otp_udfchkbox05,
               otp_precision
	    FROM   r5objtestpoints,
	           r5objects
	    WHERE  otp_object     = obj_code
	    AND    otp_object_org = obj_org
	    AND    obj_code       = @sCategory
	    AND    obj_obrtype    = N'C'

    END


